from pathlib import Path
import json
tid='DEV-PRED-ASTRA-RESULT-NORMALIZE-R5-20261008-N1E132'
roots=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
hits=[]
for root in roots:
    if root.exists():
        for p in root.rglob('*'):
            if p.is_file() and tid in p.name:
                try:
                    txt=p.read_text(errors='replace')
                except Exception:
                    continue
                hits.append((str(p),txt))
def clean(s):
    return str(s).replace('\n',' ').replace('\r',' ').replace('|','/').replace('{','(').replace('}',')')[:5000]
print('ERROR_CLASS=N1E132_NORMALIZE_RESULT')
parts=[]
for path,txt in hits[:20]:
    try:
        o=json.loads(txt)
        parts.append('PATH='+clean(path))
        for k in ['status','exit_code','error','detail','task_id','branch','worktree','commit','commit_sha','local_commit','operations']:
            if k in o: parts.append(k.upper()+'='+clean(o[k]))
    except Exception:
        parts.append('PATH='+clean(path)+' RAW='+clean(txt[:1200]))
if not parts: parts=['NO_LOCAL_RESULT_FOUND']
print('ERROR='+'|'.join(parts))
raise SystemExit(1)
